import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif

MAX_DRIVERS = 5

def design(feats):
    # Check if any feature shows strong association with outcome
    p_values = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical' or feats.types[i] == 'cohort':
            continue
        x1 = feats.x[feats.y == 1, i]
        x0 = feats.x[feats.y == 0, i]
        if len(x1) > 0 and len(x0) > 0:
            t_stat, p_val = stats.ttest_ind(x1, x0, equal_var=False)
            p_values.append((p_val, fid))

    p_values.sort()

    # If no significant features found, return empty design
    if not p_values or p_values[0][0] > 0.05:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select top features by significance
    top_features = [fid for _, fid in p_values[:5]]

    # Remove near-duplicates based on correlation matrix
    corr_matrix = np.corrcoef(feats.x[:, [feats.column(fid) for fid in top_features]])
    to_remove = set()
    for i in range(len(top_features)):
        for j in range(i+1, len(top_features)):
            if abs(corr_matrix[i,j]) >= 0.6:
                to_remove.add(top_features[j])

    selected_features = [fid for fid in top_features if fid not in to_remove]

    # If we have no features left, return empty design
    if not selected_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select best features using mutual information
    mi_scores = mutual_info_classif(feats.x[:, [feats.column(fid) for fid in selected_features]], feats.y)
    sorted_indices = np.argsort(mi_scores)[::-1][:MAX_DRIVERS]
    drivers = tuple(selected_features[i] for i in sorted_indices if mi_scores[i] > 0)

    # Build columns and products from top features
    columns = tuple(selected_features[:3])  # Limit to 3 features
    products = tuple([(a,b) for i, a in enumerate(columns) for b in columns[i+1:] if a != b])

    # Simple weighted score based on standardized values
    loadings = {fid: 1.0 for fid in columns}

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

